package app.layan.quran;
import android.os.Bundle;import android.widget.*;
public final class LayanInfoActivity extends LayanBaseActivity {
 @Override protected void onCreate(Bundle state){super.onCreate(state);frame("عن "+brand()+"","القرآن الكريم · الأحاديث · مواقيت الصلاة · القبلة");ScrollView scroll=new ScrollView(this);LinearLayout page=column();page.setPadding(dp(20),dp(12),dp(20),dp(20));LinearLayout intro=card();intro.addView(label(brand(),26,green));intro.addView(label("المهندس عبدالرحمن وائل مغاوري",23,ink));intro.addView(label("الإصدار ١٨.١٢",15,muted));intro.addView(label("حقوق تصميم ليان والإضافات الخاصة محفوظة للمهندس عبدالرحمن وائل مغاوري. المحتوى والمكونات الخارجية وفق تراخيصها.",14,muted));gap(intro,18);intro.addView(label(""+brand()+" رفيقك لقراءة القرآن الكريم والاستماع إليه، والاطلاع على التفسير وترجمات المعاني والأحاديث، ومتابعة مواقيت الصلاة واتجاه القبلة حسب موقعك.",19,ink));gap(intro,14);intro.addView(label("تجربة هادئة تساعدك على العودة إلى موضع قراءتك وحفظ علاماتك وملاحظاتك بسهولة.",17,muted));page.addView(intro);gap(page,14);page.addView(button("سياسة الخصوصية",this::privacy));scroll.addView(page);body.addView(scroll);}
 private String brand(){return getApplicationInfo().loadLabel(getPackageManager()).toString();}
 private void privacy(){LinearLayout content=card();content.addView(label("سياسة الخصوصية · "+brand()+"",25,green));String[] titles={"القراءة والمحتوى","صلاحية الموقع","الاتصال بالإنترنت","المشاركة والبيانات المحلية","التحكم في بياناتك"};String[] paragraphs={""+brand()+" لا يتطلب إنشاء حساب مستخدم. تُحفظ علامات القراءة والملاحظات والإعدادات على جهازك، وتحتوي النسخة على مكتبة الأحاديث للعمل دون إنترنت.","نطلب صلاحية الموقع عند فتح قسم الصلاة أو القبلة لحساب المواعيد أو الاتجاه حسب مكانك. يُستخدم الموقع أثناء فتح القسم، وتُحفظ آخر إحداثيات متاحة على جهازك. يستخدم قسم القبلة حساسات الهاتف أثناء ظهوره لضبط اتجاه البوصلة. لا يرسل القسمان إحداثياتك أو قراءات الحساسات إلى خادم "+brand()+" ولا يعملان كخدمة تتبّع في الخلفية.","تنزيل صفحات المصحف والتلاوات والتفسير وترجمات المعاني يحتاج إلى الاتصال بخوادم التنزيل. تتلقى خوادم التنزيل بيانات الطلب المعتادة مثل عنوان الإنترنت والملف المطلوب، وتُحفظ الملفات المنزّلة على الجهاز لاستخدامها لاحقًا. لا تستخدم هذه النسخة حسابات الإعلانات أو الإشعارات التسويقية.","عند اختيار مشاركة آية أو حديث، يفتح "+brand()+" قائمة المشاركة في الهاتف وتختار أنت التطبيق والجهة المستلمة. تُستخدم صلاحيات الملفات والإشعارات حيث يحتاجها تنزيل المحتوى أو تشغيل التلاوات.","يمكنك إلغاء صلاحية الموقع من إعدادات الهاتف أو مسح بيانات التطبيق لحذف إعداداته وبياناته المحلية. المطوّر: المهندس عبدالرحمن وائل مغاوري. آخر تحديث لهذه السياسة: ٤ أكتوبر ٢٠٢٦."};for(int i=0;i<titles.length;i++){gap(content,14);content.addView(label(titles[i],20,ink));TextView t=label(paragraphs[i],17,muted);t.setLineSpacing(dp(5),1f);content.addView(t);}ScrollView scroll=new ScrollView(this);scroll.addView(content);new LayanDialogBuilder(this).setView(scroll).setPositiveButton("تم",null).show();}
}
